    /// formatted() localizes THROUGH the concrete unit type (mph for
    /// a US locale's km/h) — the erased carrier re-specializes over
    /// every swept Dimension class before formatting.
    static func measurementFormatted(_ m: Measurement<Dimension>) -> String {
        switch m.unit {
        case let unit as UnitAcceleration: return Measurement<UnitAcceleration>(value: m.value, unit: unit).formatted()
        case let unit as UnitAngle: return Measurement<UnitAngle>(value: m.value, unit: unit).formatted()
        case let unit as UnitArea: return Measurement<UnitArea>(value: m.value, unit: unit).formatted()
        case let unit as UnitConcentrationMass: return Measurement<UnitConcentrationMass>(value: m.value, unit: unit).formatted()
        case let unit as UnitDispersion: return Measurement<UnitDispersion>(value: m.value, unit: unit).formatted()
        case let unit as UnitDuration: return Measurement<UnitDuration>(value: m.value, unit: unit).formatted()
        case let unit as UnitElectricCharge: return Measurement<UnitElectricCharge>(value: m.value, unit: unit).formatted()
        case let unit as UnitElectricCurrent: return Measurement<UnitElectricCurrent>(value: m.value, unit: unit).formatted()
        case let unit as UnitElectricPotentialDifference: return Measurement<UnitElectricPotentialDifference>(value: m.value, unit: unit).formatted()
        case let unit as UnitElectricResistance: return Measurement<UnitElectricResistance>(value: m.value, unit: unit).formatted()
        case let unit as UnitEnergy: return Measurement<UnitEnergy>(value: m.value, unit: unit).formatted()
        case let unit as UnitFrequency: return Measurement<UnitFrequency>(value: m.value, unit: unit).formatted()
        case let unit as UnitFuelEfficiency: return Measurement<UnitFuelEfficiency>(value: m.value, unit: unit).formatted()
        case let unit as UnitIlluminance: return Measurement<UnitIlluminance>(value: m.value, unit: unit).formatted()
        case let unit as UnitInformationStorage: return Measurement<UnitInformationStorage>(value: m.value, unit: unit).formatted()
        case let unit as UnitLength: return Measurement<UnitLength>(value: m.value, unit: unit).formatted()
        case let unit as UnitMass: return Measurement<UnitMass>(value: m.value, unit: unit).formatted()
        case let unit as UnitPower: return Measurement<UnitPower>(value: m.value, unit: unit).formatted()
        case let unit as UnitPressure: return Measurement<UnitPressure>(value: m.value, unit: unit).formatted()
        case let unit as UnitSpeed: return Measurement<UnitSpeed>(value: m.value, unit: unit).formatted()
        case let unit as UnitTemperature: return Measurement<UnitTemperature>(value: m.value, unit: unit).formatted()
        case let unit as UnitVolume: return Measurement<UnitVolume>(value: m.value, unit: unit).formatted()
        default: return m.formatted()
        }
    }

    @MainActor static let carrierConstructors: [String: HostFunction] = [
        "Measurement": HostFunction(name: "Measurement") { args, ctx in
            if args.labeled("value") != nil && args.labeled("unit") != nil {
                return .native(Measurement<Dimension>(value: try GeneratedDispatch.coerce(.double, args.labeled("value")!, ctx) as! Double, unit: try GeneratedDispatch.coerce(.dimension, args.labeled("unit")!, ctx) as! Dimension))
            }
            throw RuntimeError(message: "Measurement argument shape not bridged")
        },
    ]
